WITH latest_match AS (SELECT s.*, x.revenue, x.units FROM stores s JOIN LATERAL (SELECT c.revenue, c.units FROM store_sales c WHERE c.store_id = s.id AND c.sale_date <= s.opened_date ORDER BY c.sale_date DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT CASE WHEN units >= 44 THEN 'PREMIUM' ELSE 'STANDARD' END AS units_tier, COUNT(CASE WHEN city = 'Chiang Mai' THEN 1 END) AS chiang_mai_count, COUNT(CASE WHEN city = 'Tokyo' THEN 1 END) AS tokyo_count, ROUND(SUM(sqft) / NULLIF(COUNT(CASE WHEN city = 'Singapore' THEN 1 END), 0), 2) AS sqft_per_singapore, SUM(units) FILTER (WHERE city = 'Berlin') AS berlin_total_units FROM latest_match GROUP BY 1;
